<script lang="ts">import {number,percent,stamp,type Row} from '../lib/api'; import {tr} from '../lib/i18n'; export let quota:Row={}; export let scope='both'; export let rings=false; function remaining(w:Row){return number(w.remaining_percent)??(number(w.used_percent)===null?null:100-Number(w.used_percent));} function color(n:number|null){return n===null?'var(--raised)':n<25?'#F19BA0':n<60?'#F7D577':'#69E6A6';}</script>
<div class="quota-grid" class:rings>{#each [[quota.primary??{},'5 小时额度'],[quota.secondary??{},'周额度']] as [window,label],i}{#if scope!=='week'||i===1}{@const n=remaining(window)}<section class="quota surface"><div class="row between"><h3>{tr(label)}</h3><strong style:color={color(n)}>{percent(n)}</strong></div>{#if rings}<svg class="gauge" viewBox="0 0 200 110" aria-label={tr(label)}><path d="M12 98a88 88 0 0 1 176 0" fill="none" stroke="var(--raised)" stroke-width="9" stroke-linecap="round"/><path d="M12 98a88 88 0 0 1 176 0" fill="none" stroke="#82A8CA" stroke-width="9" stroke-linecap="round" pathLength="100" stroke-dasharray={`${Math.max(0,Math.min(100,n??0))} 100`}/><text x="100" y="85" text-anchor="middle" fill="currentColor" font-size="28">{percent(n)}</text></svg>{:else}<div class="meter"><div style:width={`${Math.max(0,Math.min(100,n??0))}%`} style:background={color(n)}></div></div>{/if}<small class="muted">{tr('重置')}：{stamp(window.resets_at)}</small></section>{/if}{/each}</div>
{#if quota.status==='not_applicable'}<p class="muted">{tr('API Key 模式不适用订阅额度')}</p>{:else if quota.error}<p class="error">{quota.error}</p>{/if}
